import { useState, useEffect, useCallback, useRef } from 'react';
import { authAPI } from '../services/api';
import { User } from '../types';

interface AuthState {
  isAuthenticated: boolean;
  user: User | null;
  loading: boolean;
  error: string | null;
}

export const useAuth = () => {
  const [authState, setAuthState] = useState<AuthState>({
    isAuthenticated: false,
    user: null,
    loading: true, // Start with loading true to check existing tokens
    error: null,
  });

  // Use ref to prevent multiple initialization
  const initialized = useRef(false);

  // Check for existing authentication on startup
  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;

    const checkExistingAuth = async () => {
      console.log('🔍 Checking existing authentication...');
      const token = localStorage.getItem('authToken');
      const userData = localStorage.getItem('userData');
      
      console.log('Token exists:', !!token);
      console.log('User data exists:', !!userData);
      console.log('Token value:', token ? 'present' : 'missing');
      console.log('User data value:', userData ? 'present' : 'missing');
      
      if (token && userData) {
        try {
          console.log('Found existing auth token, restoring state...');
          const user = JSON.parse(userData);
          console.log('Parsed user data:', user);
          
          // For now, trust the localStorage data without backend validation
          // This avoids potential network issues during startup
          const newAuthState = {
            isAuthenticated: true,
            user: user,
            loading: false,
            error: null,
          };
          
          console.log('Setting auth state to authenticated:', newAuthState);
          setAuthState(newAuthState);
          console.log('✅ Restored authentication state from localStorage');
        } catch (error) {
          console.error('❌ Error restoring auth state:', error);
          localStorage.removeItem('authToken');
          localStorage.removeItem('userData');
          setAuthState({
            isAuthenticated: false,
            user: null,
            loading: false,
            error: null,
          });
        }
      } else {
        console.log('No existing auth token found');
        setAuthState(prev => ({ ...prev, loading: false }));
      }
    };

    checkExistingAuth();
  }, []);

  // Log authentication state changes
  useEffect(() => {
    console.log('🔄 Auth state changed:', {
      isAuthenticated: authState.isAuthenticated,
      loading: authState.loading,
      user: authState.user?.username,
      error: authState.error
    });
  }, [authState]);

  const login = useCallback(async (username: string, password: string) => {
    console.log('🚀 Starting login process...');
    
    setAuthState(prev => ({ ...prev, loading: true, error: null }));
    
    try {
      console.log('📡 Attempting login with:', { username, password: '***' });
      const response = await authAPI.login(username, password);
      console.log('✅ Login response received:', response);
      
      // Store in localStorage first
      localStorage.setItem('authToken', response.token);
      localStorage.setItem('userData', JSON.stringify(response.user));
      console.log('💾 Auth data stored in localStorage');
      console.log('💾 Token stored:', response.token ? 'present' : 'missing');
      console.log('💾 User data stored:', response.user ? 'present' : 'missing');
      
      // Then update state
      const newAuthState = {
        isAuthenticated: true,
        user: response.user,
        loading: false,
        error: null,
      };
      
      console.log('🔄 Setting authentication state to true:', newAuthState);
      setAuthState(newAuthState);
      console.log('🔄 Auth state updated, isAuthenticated should be true');
      
      console.log('✅ Login successful, returning success');
      return { success: true };
    } catch (error: any) {
      console.error('❌ Login error:', error);
      console.error('Error response:', error.response);
      const errorMessage = error.response?.data?.message || 'Login failed';
      
      setAuthState(prev => ({
        ...prev,
        loading: false,
        error: errorMessage,
      }));
      
      return { success: false, error: errorMessage };
    }
  }, []);

  const logout = useCallback(async () => {
    console.log('🚪 Starting logout process...');
    try {
      await authAPI.logout();
      console.log('✅ Logout API call successful');
    } catch (error) {
      console.error('❌ Logout API error:', error);
    } finally {
      // Clear localStorage
      localStorage.removeItem('authToken');
      localStorage.removeItem('userData');
      console.log('🗑️ Auth data cleared from localStorage');
      
      // Update state
      setAuthState({
        isAuthenticated: false,
        user: null,
        loading: false,
        error: null,
      });
      console.log('✅ Logout completed');
    }
  }, []);

  // Debug function to manually set authentication state
  const debugSetAuth = useCallback((authenticated: boolean) => {
    console.log('🔧 Debug: Manually setting auth state to:', authenticated);
    if (authenticated) {
      const mockUser = { id: 1, username: 'debug_user', role: 'admin' };
      localStorage.setItem('authToken', 'debug_token');
      localStorage.setItem('userData', JSON.stringify(mockUser));
      setAuthState({
        isAuthenticated: true,
        user: mockUser,
        loading: false,
        error: null,
      });
    } else {
      localStorage.removeItem('authToken');
      localStorage.removeItem('userData');
      setAuthState({
        isAuthenticated: false,
        user: null,
        loading: false,
        error: null,
      });
    }
  }, []);

  return {
    ...authState,
    login,
    logout,
    debugSetAuth,
  };
};
